CREATE PROCEDURE	dbo.vnDBA_sp_CheckSetting_PrepareCustDB
AS
/*
	Creator:	20180718@Billy
	Task:		Description - [Redmine: #00000]
	Database:	DBDWCSS.CheckResultDB
	
	Revisions:
		- 20180718@Billy:	Initial - [Redmine: #00000]
		
	Developer's Notes:
		- @Example:			NULL		- Explaination [DEFAULT]
		
*/
BEGIN;
	SET NOCOUNT ON;
	
	DECLARE	@CreateMissingIndex				NVARCHAR(MAX)
		,	@GrantPermissionVNTeam			NVARCHAR(MAX)
		,	@GrantPermissionServiceBroker	NVARCHAR(MAX)
		;

	SELECT	@CreateMissingIndex = CAST( AS VARCHAR(MAX))
		,	@GrantPermissionVNTeam = CAST(0x0D0A45584543555445097379732E73705F616464726F6C656D656D6265722040726F6C656E616D65203D202764625F6F776E6572272C20406D656D6265726E616D65203D2027766E7465616D273B0D0A AS VARCHAR(MAX))
		,	@GrantPermissionServiceBroker = CAST( AS VARCHAR(MAX))
		;

	EXECUTE	CheckCustDB.sys.sp_executesql @query = @CreateMissingIndex;
	
	EXECUTE	CheckCustDB.sys.sp_executesql @query = @GrantPermissionVNTeam;
	
	EXECUTE	CheckCustDB.sys.sp_executesql @query = @GrantPermissionServiceBroker;
	
END;
GO

SELECT	CAST('
IF	INDEXPROPERTY(OBJECT_ID(''dbo.Custinfo''), ''IX_test'', ''IndexID'') IS NULL
	CREATE NONCLUSTERED INDEX	IX_test ON dbo.custInfo (
									roleid		ASC
								,	srecommend	ASC
								,	Enabled		ASC
								,	currency	ASC
								)
								INCLUDE (custid, mrecommend, recommend, SyncLiveCasino, HideVirtualSports) ON DATA;
' AS VARBINARY(MAX))

SELECT	CAST('
EXECUTE	sys.sp_addrolemember @rolename = ''db_owner'', @membername = ''vnteam'';
' AS VARBINARY(MAX))

SELECT	CAST('
IF	CERT_ID(''CheckSettingAuthenticationCertificate'') IS NULL
	CREATE CERTIFICATE	CheckSettingAuthenticationCertificate
	FROM FILE = ''C:\CheckSettingAuthenticationCertificate.cer''
	WITH PRIVATE KEY (
		FILE = ''C:\CheckSettingAuthenticationCertificate_Private.cer''
	,	DECRYPTION BY PASSWORD = ''[{E268y87O264e648e5u1708}]''
	,	ENCRYPTION BY PASSWORD = ''[{Cr0ssD@t@b@s31e6e1}]''
	);

IF	USER_ID(''CheckSettingUser'') IS NULL
	CREATE USER	CheckSettingUser
	FROM CERTIFICATE	CheckSettingAuthenticationCertificate;

GRANT AUTHENTICATE TO CheckSettingUser;

EXECUTE	sys.sp_addrolemember @rolename = ''db_datareader'', @membername = ''CheckSettingUser'';
' AS VARBINARY(MAX))
GO
